<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Users, BookOpen, GraduationCap, PieChart, Download, Info } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import StatCard from '../components/StatCard.vue'
import AnalyticsChart from '../components/AnalyticsChart.vue'
import { api, query, type Dashboard } from '../lib/api'
import { csvDownload } from '../lib/format'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'
const workspace = useWorkspace(), { loading, error, run } = useAsync(), data = ref<Dashboard>()
async function load() { await run(async () => { data.value = await api<Dashboard>('/dashboard' + query({ termId: workspace.termId })) }) }
watch(() => workspace.termId, load, { immediate: true })
const occupancy = computed(() => { const capacity = data.value?.capacity.reduce((sum, item) => sum + item.capacity, 0) || 0; return capacity ? ((data.value?.capacity.reduce((sum, item) => sum + item.enrolledCount, 0) || 0) / capacity * 100).toFixed(1) + '%' : '—' })
const distributionOption = computed(() => ({ color: ['#bba277', '#b7c69d', '#95b17e', '#678b60', '#355f49'], tooltip: { trigger: 'item', formatter: '{b}：{c}人（{d}%）' }, legend: { bottom: 5, textStyle: { color: '#91a17f', fontSize: 10 }, icon: 'circle', itemWidth: 7, itemHeight: 7 }, series: [{ type: 'pie', radius: ['43%', '69%'], center: ['50%', '45%'], itemStyle: { borderRadius: 4, borderColor: '#fff', borderWidth: 3 }, label: { show: false }, emphasis: { label: { show: true, fontSize: 12, color: '#5a7650' } }, data: data.value?.gradeDistribution.map(item => ({ name: item.label, value: item.count })) || [] }] }))
const capacityOption = computed(() => { const items = [...(data.value?.capacity || [])].sort((a, b) => b.enrolledCount / (b.capacity || 1) - a.enrolledCount / (a.capacity || 1)).slice(0, 8).reverse(); return { color: ['#8faa75', '#e9f0df'], grid: { left: 110, right: 25, top: 10, bottom: 35 }, tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } }, legend: { bottom: 0, textStyle: { color: '#96a486', fontSize: 10 }, itemWidth: 7, itemHeight: 7 }, xAxis: { type: 'value', minInterval: 1, axisLabel: { color: '#a1ae93', fontSize: 9 }, splitLine: { lineStyle: { color: '#f0f3e9' } } }, yAxis: { type: 'category', data: items.map(item => item.title.length > 9 ? item.title.slice(0, 9) + '…' : item.title), axisLine: { show: false }, axisTick: { show: false }, axisLabel: { color: '#819572', fontSize: 10 } }, series: [{ name: '已选人数', type: 'bar', stack: 'capacity', barMaxWidth: 13, data: items.map(item => item.enrolledCount), itemStyle: { borderRadius: [0, 3, 3, 0] } }, { name: '剩余名额', type: 'bar', stack: 'capacity', barMaxWidth: 13, data: items.map(item => Math.max(0, item.capacity - item.enrolledCount)), itemStyle: { borderRadius: [0, 3, 3, 0] } }] } })
function download() { if (data.value) csvDownload(`课序-${workspace.currentTerm?.name || '教学分析'}-容量分析.csv`, [['教学班', '课程名称', '已选人数', '班级容量', '利用率'], ...data.value.capacity.map(item => [item.sectionId, item.title, item.enrolledCount, item.capacity, item.capacity ? (item.enrolledCount / item.capacity * 100).toFixed(1) + '%' : '—'])]) }
</script>
<template><PageHeading eyebrow="SEE THE STORY IN THE NUMBERS" title="教学分析" description="从真实教学记录出发，看见课程安排与学习成果的全貌。"><select v-model="workspace.termId" class="select-control" aria-label="选择学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select><button class="button button-secondary" :disabled="!data" @click="download"><Download :size="14"/>导出容量分析</button></PageHeading><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load"/><template v-else-if="data"><section class="stats-grid"><StatCard label="在册学生" :value="data.students" note="学生档案实时统计"><Users/></StatCard><StatCard label="实际选课记录" :value="data.enrollments" note="当前学期有效选课"><BookOpen/></StatCard><StatCard label="已发布成绩均分" :value="data.averageGrade == null ? '—' : Number(data.averageGrade).toFixed(1)" note="只统计正式发布的成绩"><GraduationCap/></StatCard><StatCard label="教学班名额利用率" :value="occupancy" note="已选人数 / 总容量" accent><PieChart/></StatCard></section><div class="chart-grid"><section class="card"><div class="card-header"><div><h2>正式成绩分布</h2><p>已发布成绩的真实人数 · 未发布草稿不计入</p></div></div><div class="chart-body"><AnalyticsChart v-if="data.gradeDistribution.some(item => item.count > 0)" :option="distributionOption" :label="data.gradeDistribution.map(item => item.label + '：' + item.count + '人').join('；')"/><StatePanel v-else title="暂时还没有已发布成绩" description="教师正式发布成绩后，将自动形成成绩分布。"/></div></section><section class="card"><div class="card-header"><div><h2>课程名额利用情况</h2><p>按利用率展示前8个教学班 · 鼠标悬停查看人数</p></div></div><div class="chart-body"><AnalyticsChart v-if="data.capacity.length" :option="capacityOption" label="教学班已选人数与剩余名额，下方表格提供完整数值。"/><StatePanel v-else title="暂无教学班容量数据"/></div></section></div><div class="notice-banner"><Info :size="16"/><span>图表与下方明细来自同一次真实查询，不使用随机数或预设趋势。点击教学班可继续查看该班选课记录。</span></div><section class="card"><div class="card-header"><div><h2>教学班容量明细</h2><p>共 {{ data.capacity.length }} 个教学班 · 候补总数 {{ data.waiting }} 人</p></div><button class="text-button" @click="load">刷新统计 ↻</button></div><StatePanel v-if="!data.capacity.length" title="还没有容量记录"/><div v-else class="table-wrap"><table><caption class="sr-only">教学班容量分析明细</caption><thead><tr><th>课程 / 教学班</th><th>已选人数</th><th>总容量</th><th>剩余名额</th><th>利用率</th><th>查看记录</th></tr></thead><tbody><tr v-for="item in data.capacity" :key="item.sectionId"><td><strong>{{ item.title }}</strong><small>{{ item.sectionId }}</small></td><td>{{ item.enrolledCount }}</td><td>{{ item.capacity }}</td><td>{{ Math.max(0, item.capacity - item.enrolledCount) }}</td><td><span class="tag" :class="{ 'tag-gold': item.enrolledCount >= item.capacity }">{{ item.capacity ? (item.enrolledCount / item.capacity * 100).toFixed(1) : '0.0' }}%</span></td><td><RouterLink :to="{ path: '/admin/enrollments', query: { sectionId: item.sectionId } }" class="text-button">选课明细 ↗</RouterLink></td></tr></tbody></table></div></section></template></template>
